class Solution {
    public String bestWayToPack(String s) {
        StringBuilder stack = new StringBuilder();
        List<Integer> delayed = new ArrayList<>();
        for (char ch : s.toCharArray()) {
            while (stack.length() > 0 && stack.charAt(stack.length() - 1) > ch) {
                int d = stack.charAt(stack.length() - 1) - '0';
                stack.deleteCharAt(stack.length() - 1);
                delayed.add(Math.min(d + 1, 9));
            }
            stack.append(ch);
        }
        for (int d : delayed) stack.append(d);
        char[] all = stack.toString().toCharArray();
        Arrays.sort(all);
        return new String(all);
    }
}

class Solution {
public:
    string bestWayToPack(string s) {
        string stk;
        vector<int> delayed;
        for (char ch : s) {
            while (!stk.empty() && stk.back() > ch) {
                int d = stk.back() - '0';
                stk.pop_back();
                delayed.push_back(min(d + 1, 9));
            }
            stk.push_back(ch);
        }
        for (int d : delayed) stk.push_back('0' + d);
        sort(stk.begin(), stk.end());
        return stk;
    }
};
